using Godot;
using System;
public partial class MigrationScene {
 void FamilyFinishMaterials(Node3D root,bool basement){foreach(var item in root.FindChildren("*","MeshInstance3D",true,false)){if(item is not MeshInstance3D mesh||mesh.MaterialOverride is not ShaderMaterial material)continue;var value=material.GetShaderParameter("base_color");if(value.VariantType!=Variant.Type.Color)continue;Color color=value.AsColor();if(!basement&&color.IsEqualApprox(new Color(.42f,.47f,.39f)))mesh.MaterialOverride=WillowSiding();else if(color.IsEqualApprox(Wood))mesh.MaterialOverride=Textured(color,0,.5f);else if(mesh.Mesh is BoxMesh box&&box.Size.X>=3&&box.Size.Y>=2)mesh.MaterialOverride=Textured(color,basement?1:0,.45f);else if(mesh.Mesh is BoxMesh floor&&floor.Size.X>=8&&floor.Size.Y<.6)mesh.MaterialOverride=Textured(basement?new Color(.35f,.34f,.29f):new Color(.44f,.35f,.23f),basement?1:0,.4f);}}
 void FamilyExteriorDetails(Node3D n){WillowUpperFloor(n);WillowRoof(n);WillowPorch(n);WillowWindow(n,-3.75f,5.1f,6.14f,false,true);WillowWindow(n,3.75f,5.1f,6.14f,true);WillowWindow(n,-1.25f,5.1f,6.79f,false);WillowWindow(n,1.25f,5.1f,6.79f,false,true);for(int side=-1;side<=1;side+=2){Box(n,new(side*4.85f,3.3f,6.17f),new(.15f,6.6f,.12f),new(.52f,.49f,.43f));Box(n,new(side*2.52f,5,6.82f),new(.15f,3.4f,.12f),new(.52f,.49f,.43f));for(int i=0;i<7;i++)Box(n,new(side*(2.8f+i*.3f),6.45f,6.2f),new(.12f,.20f,.22f),new(.46f,.43f,.36f));Box(n,new(side*3.4f,.25f,9.8f),new(1.8f,.5f,.8f),new(.30f,.28f,.22f));for(int i=0;i<7;i++){var stem=new Vector3(side*3.4f+(i%3-1)*.35f,.5f,9.65f+(i/3)*.23f);Tube(n,stem,stem+Vector3.Up*.5f,.012f,new(.27f,.30f,.17f));Ellipsoid(n,stem+Vector3.Up*.5f,new(.06f,.025f,.06f),new(.50f,.43f,.27f));}}for(int i=0;i<8;i++){float x=-4.5f+i*1.2f;Box(n,new(x,.55f,18),new(.08f,1.1f,.08f),Wood);if(i!=3&&i!=4)Tube(n,new(x,.7f,18),new(x+1.15f,.7f,18),.025f,Wood);}n.AddChild(new OmniLight3D{Position=new(0,2.7f,0),LightColor=new(1,.78f,.53f),LightEnergy=.75f,OmniRange=10});}
 void FamilyRoomDetails(Node3D n,bool basement){var color=new Color(.50f,.46f,.36f);for(int i=0;i<5;i++){float z=basement?-17+i*.4f:4.5f;var at=new Vector3(basement?-.7f+i*.25f:-2+i*.3f,.045f,z);Box(n,at,new(.20f,.04f,.29f),color);}if(basement){Box(n,new(2.3f,.04f,-12),new(2.7f,.04f,2.6f),new(.30f,.25f,.19f));for(int side=-1;side<=1;side+=2){Box(n,new(2.3f+side*1.15f,.45f,-12),new(.5f,.15f,.55f),Wood);Box(n,new(2.3f+side*1.15f,.8f,-12.2f),new(.5f,.7f,.10f),Wood);for(int leg=-1;leg<=1;leg+=2)Tube(n,new(2.3f+side*1.15f+leg*.17f,.4f,-12),new(2.3f+side*1.15f+leg*.17f,0,-12),.025f,Wood);}for(int i=0;i<9;i++)Box(n,new(-5.8f,1.4f+i*.06f,-18),new(.02f,.025f,.10f),new(.22f,.22f,.18f));}else{Box(n,new(3.3f,.05f,4.8f),new(.6f,.1f,.8f),new(.42f,.32f,.22f));for(int i=0;i<4;i++)Tube(n,new(3.05f+i*.16f,.1f,4.8f),new(3.05f+i*.16f,.3f,4.8f),.05f,new(.46f,.37f,.25f));}
  var dustMaterial=new StandardMaterial3D{AlbedoColor=new(.65f,.60f,.48f,.12f),Transparency=BaseMaterial3D.TransparencyEnum.Alpha,ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded};n.AddChild(new CpuParticles3D{Position=new(0,2.5f,basement?-14:0),Amount=28,Lifetime=8,Preprocess=4,Direction=Vector3.Down,Spread=90,Gravity=Vector3.Zero,InitialVelocityMin=.03f,InitialVelocityMax=.09f,EmissionShape=CpuParticles3D.EmissionShapeEnum.Box,EmissionBoxExtents=new(4,.5f,4),Mesh=new SphereMesh{Radius=.012f,Height=.024f,RadialSegments=4,Rings=2,Material=dustMaterial}});
 }
